/* [FIX-1] IIFE — tout le contenu est isolé du scope global */
(function () {
  'use strict';

  var LGM = window.LGM;

/* ================================================================
   xm-player.js — LECTEUR DE MUSIQUE CHIPTUNE AU FORMAT .XM
   ================================================================
   Ce fichier contient :
   - La musique chiptune encodée en base64 (XM_BASE64)
   - Un parseur minimal du format FastTracker II (.XM)
   - Un moteur de lecture audio via Web Audio API (ScriptProcessor)

   POUR UN DÉBUTANT :
   Le format .XM (Extended Module) est un format de musique "tracker"
   populaire dans la scène démo/chiptune des années 90. Au lieu de
   stocker de l'audio brut (comme le MP3), il stocke des notes,
   des instruments (petits échantillons) et des effets.
   
   Le parseur lit ce format binaire et le "joue" en temps réel
   via la Web Audio API du navigateur.
   ================================================================ */

// État du lecteur
let xmPlaying = false;        // true si la musique joue
let xmAudioCtx = null;        // Contexte Web Audio
let xmScriptNode = null;      // Noeud ScriptProcessor (rendu audio)

// Musique chiptune encodée en base64 (~57 Ko de données binaires)
const XM_BASE64 = '';

/**
 * Décode une chaîne base64 en Uint8Array (tableau d'octets).
 * @param {string} b64 - La chaîne encodée en base64
 * @returns {Uint8Array}
 */
function b64toU8(b64) {
  var bin = atob(b64);
  var buf = new Uint8Array(bin.length);
  for (var i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf;
}

// ---- Minimal XM Parser ----
function parseXM(data) {
  const d = new DataView(data.buffer);
  const headerSize = d.getUint32(60, true);
  const songLen = d.getUint16(64, true);
  const numChannels = d.getUint16(68, true);
  const numPatterns = d.getUint16(70, true);
  const numInstruments = d.getUint16(72, true);
  const flags = d.getUint16(74, true);
  const tempo = d.getUint16(76, true);
  const bpm = d.getUint16(78, true);
  const order = [];
  for (let i = 0; i < songLen; i++) order.push(data[80 + i]);

  let offset = 60 + headerSize;
  const patterns = [];
  for (let p = 0; p < numPatterns; p++) {
    const patHeaderLen = d.getUint32(offset, true);
    const numRows = d.getUint16(offset + 5, true);
    const packedSize = d.getUint16(offset + 7, true);
    offset += patHeaderLen;
    const rows = [];
    const end = offset + packedSize;
    for (let r = 0; r < numRows; r++) {
      const row = [];
      for (let c = 0; c < numChannels; c++) {
        let note = 0, instr = 0, vol = 0, fx = 0, fxp = 0;
        if (offset < end) {
          const b = data[offset++];
          if (b & 0x80) {
            if (b & 0x01) note = data[offset++];
            if (b & 0x02) instr = data[offset++];
            if (b & 0x04) vol = data[offset++];
            if (b & 0x08) fx = data[offset++];
            if (b & 0x10) fxp = data[offset++];
          } else {
            note = b;
            instr = data[offset++];
            vol = data[offset++];
            fx = data[offset++];
            fxp = data[offset++];
          }
        }
        row.push({ note, instr, vol, fx, fxp });
      }
      rows.push(row);
    }
    offset = end;
    patterns.push(rows);
  }

  // Parse instruments (just get sample data for basic playback)
  const instruments = [];
  for (let i = 0; i < numInstruments; i++) {
    const instSize = d.getUint32(offset, true);
    const numSamples = d.getUint16(offset + 27, true);
    const inst = { samples: [] };
    if (numSamples > 0) {
      const sampleHeaderSize = d.getUint32(offset + 29, true);
      const noteMap = [];
      for (let n = 0; n < 96; n++) noteMap.push(data[offset + 33 + n]);
      inst.noteMap = noteMap;
      offset += instSize;
      const sampleHeaders = [];
      for (let s = 0; s < numSamples; s++) {
        const sLen = d.getUint32(offset, true);
        const sLoopStart = d.getUint32(offset + 4, true);
        const sLoopLen = d.getUint32(offset + 8, true);
        const sVol = data[offset + 12];
        const sFt = d.getInt8(offset + 13);
        const sFlags = data[offset + 14];
        const sPan = data[offset + 15];
        const sRelNote = d.getInt8(offset + 16);
        sampleHeaders.push({ len: sLen, loopStart: sLoopStart, loopLen: sLoopLen, vol: sVol, finetune: sFt, flags: sFlags, pan: sPan, relNote: sRelNote });
        offset += sampleHeaderSize;
      }
      for (let s = 0; s < numSamples; s++) {
        const sh = sampleHeaders[s];
        const is16 = sh.flags & 0x10;
        const numSmp = is16 ? sh.len / 2 : sh.len;
        const pcm = new Float32Array(numSmp);
        let prev = 0;
        if (is16) {
          for (let j = 0; j < numSmp; j++) {
            prev += d.getInt16(offset + j * 2, true);
            if (prev > 32767) prev -= 65536;
            if (prev < -32768) prev += 65536;
            pcm[j] = prev / 32768;
          }
          offset += sh.len;
        } else {
          for (let j = 0; j < numSmp; j++) {
            prev += d.getInt8(offset + j);
            if (prev > 127) prev -= 256;
            if (prev < -128) prev += 256;
            pcm[j] = prev / 128;
          }
          offset += sh.len;
        }
        const loopSamples = is16 ? sh.loopLen / 2 : sh.loopLen;
        const loopStartSmp = is16 ? sh.loopStart / 2 : sh.loopStart;
        inst.samples.push({ pcm, vol: sh.vol, finetune: sh.finetune, relNote: sh.relNote, flags: sh.flags, loopStart: loopStartSmp, loopLen: loopSamples, pan: sh.pan });
      }
    } else {
      offset += instSize;
    }
    instruments.push(inst);
  }

  return { songLen, numChannels, numPatterns, numInstruments, tempo, bpm, order, patterns, instruments, flags };
}

// ---- XM Playback Engine (ScriptProcessor) ----
function playXM(xmData) {
  const mod = parseXM(xmData);
  if (!xmAudioCtx) xmAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if (xmAudioCtx.state === 'suspended') xmAudioCtx.resume();

  const sRate = xmAudioCtx.sampleRate;
  const bufSize = 4096;
  xmScriptNode = xmAudioCtx.createScriptProcessor(bufSize, 0, 2);

  // Playback state
  let curOrder = 0, curRow = 0, curTick = 0;
  let ticksPerRow = mod.tempo || 6;
  let bpm = mod.bpm || 125;
  let samplesPerTick = Math.round(sRate * 2.5 / bpm);
  let tickSamplePos = 0;

  // Channel state
  const channels = [];
  for (let c = 0; c < mod.numChannels; c++) {
    channels.push({ smpData: null, smpPos: 0, smpStep: 0, vol: 0, pan: 128, period: 0, loopStart: 0, loopLen: 0, loopType: 0, active: false });
  }

  function noteToFreq(note, finetune, relNote) {
    const n = note - 1 + relNote;
    const ft = finetune / 128;
    return 8363 * Math.pow(2, (n - 48 + ft) / 12);
  }

  function processRow() {
    if (curOrder >= mod.songLen) { curOrder = 0; }
    const patIdx = mod.order[curOrder];
    if (patIdx >= mod.patterns.length) { curOrder++; return; }
    const pat = mod.patterns[patIdx];
    if (curRow >= pat.length) { curRow = 0; curOrder++; return; }
    const row = pat[curRow];

    for (let c = 0; c < mod.numChannels; c++) {
      const cell = row[c];
      const ch = channels[c];
      if (cell.note > 0 && cell.note < 97) {
        const instIdx = (cell.instr || 0) - 1;
        if (instIdx >= 0 && instIdx < mod.instruments.length) {
          const inst = mod.instruments[instIdx];
          let smpIdx = 0;
          if (inst.noteMap) smpIdx = inst.noteMap[Math.min(cell.note - 1, 95)] || 0;
          if (smpIdx < inst.samples.length) {
            const smp = inst.samples[smpIdx];
            ch.smpData = smp.pcm;
            ch.smpPos = 0;
            ch.vol = smp.vol / 64;
            ch.pan = smp.pan;
            ch.loopStart = smp.loopStart;
            ch.loopLen = smp.loopLen;
            ch.loopType = smp.flags & 3;
            const freq = noteToFreq(cell.note, smp.finetune, smp.relNote);
            ch.smpStep = freq / sRate;
            ch.active = true;
          }
        }
      } else if (cell.note === 97) {
        ch.active = false;
      }
      if (cell.vol >= 0x10 && cell.vol <= 0x50) {
        ch.vol = (cell.vol - 0x10) / 64;
      }
      // Speed/BPM effects
      if (cell.fx === 0x0F) {
        if (cell.fxp > 0 && cell.fxp < 0x20) { ticksPerRow = cell.fxp; }
        else if (cell.fxp >= 0x20) { bpm = cell.fxp; samplesPerTick = Math.round(sRate * 2.5 / bpm); }
      }
    }
  }

  function processTick() {
    if (curTick === 0) processRow();
    curTick++;
    if (curTick >= ticksPerRow) {
      curTick = 0;
      curRow++;
      if (curOrder < mod.songLen) {
        const patIdx = mod.order[curOrder];
        if (patIdx < mod.patterns.length && curRow >= mod.patterns[patIdx].length) {
          curRow = 0;
          curOrder++;
        }
      }
    }
  }

  xmScriptNode.onaudioprocess = function(e) {
    const outL = e.outputBuffer.getChannelData(0);
    const outR = e.outputBuffer.getChannelData(1);
    for (let i = 0; i < bufSize; i++) {
      if (tickSamplePos >= samplesPerTick) {
        tickSamplePos = 0;
        processTick();
      }
      tickSamplePos++;
      let mixL = 0, mixR = 0;
      for (let c = 0; c < mod.numChannels; c++) {
        const ch = channels[c];
        if (!ch.active || !ch.smpData) continue;
        const pos = Math.floor(ch.smpPos);
        if (pos >= ch.smpData.length) {
          if (ch.loopType && ch.loopLen > 2) {
            ch.smpPos = ch.loopStart + ((pos - ch.loopStart) % ch.loopLen);
          } else {
            ch.active = false; continue;
          }
        }
        const smp = ch.smpData[Math.floor(ch.smpPos)] * ch.vol * 0.5;
        const panR = ch.pan / 255;
        const panL = 1 - panR;
        mixL += smp * panL;
        mixR += smp * panR;
        ch.smpPos += ch.smpStep;
        // Handle loop
        if (ch.loopType && ch.loopLen > 2 && ch.smpPos >= ch.loopStart + ch.loopLen) {
          ch.smpPos = ch.loopStart + ((ch.smpPos - ch.loopStart) % ch.loopLen);
        }
      }
      // Soft clip
      outL[i] = Math.max(-1, Math.min(1, mixL));
      outR[i] = Math.max(-1, Math.min(1, mixR));
    }
  };

  xmScriptNode.connect(xmAudioCtx.destination);
}

function toggleMusic() {
  const btn = document.getElementById('musicBtn');
  if (xmPlaying) {
    stopXm();
    btn.textContent = '\u266B PLAY XM';
    btn.classList.remove('playing');
    return;
  }
  try {
    const xmBytes = b64toU8(XM_BASE64);
    playXM(xmBytes);
    xmPlaying = true;
    btn.textContent = '\u266B STOP XM';
    btn.classList.add('playing');
  } catch(err) {
    console.error('XM playback error:', err);
    LGM.toast('Erreur lecture XM: ' + err.message);
    btn.textContent = '\u266B PLAY XM';
  }
}

function stopXm() {
  xmPlaying = false;
  try {
    if (xmScriptNode) { xmScriptNode.disconnect(); xmScriptNode = null; }
  } catch(e) {}
}


  /* [FIX-1] Exposition publique — toggleMusic est appelé depuis index.html */
  LGM.toggleMusic = toggleMusic;

})();
